def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    units = int(supply / WATER_REQ)
    if units < 1:
        units = 1

    prev_bids = []
    desperate_opp = 0
    rich_opp = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
            desperate_opp += 1
        if opp.get('budget', 0) > 300:
            rich_opp += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if not alive:
        return float(min(budget, 18.0))

    pressure = 0
    if units <= 1:
        pressure += 3
    elif units == 2:
        pressure += 2
    else:
        pressure += 1

    if no_water_days >= 2 or hp <= 2:
        pressure += 3
    elif no_water_days >= 1 or hp <= 4:
        pressure += 2
    elif hp <= 6:
        pressure += 1

    if highest_prev >= 100:
        pressure += 2
    elif highest_prev >= 80:
        pressure += 1

    if desperate_opp >= 2:
        pressure += 1
    if rich_opp >= 2:
        pressure += 1

    if day >= 8:
        pressure += 1

    if pressure <= 2:
        bid = max(8.0, avg_prev * 0.45)
    elif pressure == 3:
        bid = max(18.0, highest_prev * 0.55)
    elif pressure == 4:
        bid = max(32.0, highest_prev * 0.72 + 2.0)
    elif pressure == 5:
        bid = max(48.0, highest_prev * 0.84 + 3.0)
    else:
        bid = max(62.0, highest_prev * 0.92 + 4.0)

    if units <= 1 and (no_water_days >= 1 or hp <= 4):
        bid = max(bid, 78.0)

    if highest_prev > 110:
        bid = min(bid, 96.0)

    reserve = 0.0
    if hp >= 7 and no_water_days == 0 and day <= 5:
        reserve = 20.0
    elif hp >= 5 and day <= 7:
        reserve = 10.0

    affordable = max(0.0, budget - reserve)
    if affordable <= 0:
        affordable = budget * 0.5

    bid = min(bid, affordable)
    bid = min(bid, budget)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 85.0))

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday's trace
    prev_bids = []
    prev_hp_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(prev.get('hp_after')))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Scarcity factor: with supply 15-25 and requirement 9, scarcity is when supply is near 15.
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0

    # If we are in danger, increase bid.
    danger = 0.0
    if hp <= 2.0:
        danger = 1.0
    elif hp <= 4.0:
        danger = 0.7
    else:
        danger = 0.2

    # If we've already had no water, escalate.
    if no_water_days >= 2:
        danger = max(danger, 0.9)
    elif no_water_days == 1:
        danger = max(danger, 0.6)

    # Rival pressure: Cindy/David were high spenders; use highest_prev_bid as a ceiling signal.
    # Target bid: moderately below the highest_prev_bid to avoid overpaying, but above a base when scarce.
    base = DAILY_SALARY * (0.38 + 0.25 * scarcity)  # ~0.38-0.63 of salary
    pressure = 0.0
    if highest_prev_bid > 0.0:
        # If someone was bidding very high, we must match more often.
        pressure = 0.25 * (highest_prev_bid / (DAILY_SALARY + 1e-9))

    # Choose multiplier depending on danger.
    mult = 0.55 + 0.45 * danger
    target = base * mult

    # If yesterday's highest bid was extremely high, lift target closer to it.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(target, min(DAILY_SALARY * 0.75, highest_prev_bid * 0.75))
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        target = max(target, min(DAILY_SALARY * 0.65, highest_prev_bid * 0.6))

    # Ensure we don't bid more than we can afford, and keep within reasonable bounds.
    bid = min(budget, target)

    # Additional safeguard: if budget is low, still try to secure when very scarce.
    if bid <= 0.0:
        bid = 0.0
    if bid < DAILY_SALARY * 0.15 and scarcity > 0.6 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * (0.25 + 0.2 * scarcity))

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}

    prev_bids = []
    for oid, opp in alive_opponents.items():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))

    # Base bid: 50% of salary = 70
    base_bid = DAILY_SALARY * 0.5

    if not prev_bids:
        # No history: use aggressive but safe
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.95)
        return min(budget, base_bid)

    max_prev = max(prev_bids)
    avg_prev = sum(prev_bids) / len(prev_bids)

    # Decision based on HP and opponent pressure
    if hp <= 2:
        # Desperate: bid high to survive
        target = max(base_bid, max_prev + 2.0)
        return min(budget, min(target, DAILY_SALARY * 0.98))
    elif hp <= 4:
        # Moderate risk: outbid average
        target = max(base_bid, avg_prev + 1.5)
        return min(budget, min(target, DAILY_SALARY * 0.85))
    else:
        # Healthy: try to save, but still competitive
        target = max(base_bid, avg_prev + 0.5)
        return min(budget, min(target, DAILY_SALARY * 0.7))
